const payload = $input.first().json.body || {};

if (payload.schemaVersion !== 1 || payload.source !== 'elevenlabs') throw new Error('Unsupported post-call payload');
if (!payload.userId || !/^\S+@\S+\.\S+$/.test(payload.userId)) throw new Error('Completed call has no usable contact email');

const analysis = payload.dataCollection || {};
const value = (key, fallback = '') => { const item = analysis[key]; return item && typeof item === 'object' && 'value' in item ? String(item.value || fallback).trim() : String(item || fallback).trim(); };
const disposition = value('disposition', payload.callSuccessful ? 'follow_up' : 'no_answer');
const summary = payload.transcriptSummary || value('summary', 'No summary was returned.');
const nextStep = value('next_step', disposition === 'qualified' ? 'Arrange a human discovery conversation.' : 'Review the callback record.');
const escalation = value('human_escalation_needed', 'no');
const language = value('callback_language', 'unknown');
const conversationId = payload.conversationId || '';

return [{ json: {
  email: payload.userId.toLowerCase(),
  conversationId,
  disposition, summary, nextStep, escalation, language,
  eventType: payload.type || '', callStatus: payload.status || '',
  completedAt: payload.eventTimestamp || new Date().toISOString(),
  noteBody: [
    'Voice callback record',
    'Language: ' + language,
    'Outcome: ' + disposition,
    'Summary: ' + summary,
    'Next step: ' + nextStep,
    'Human escalation: ' + escalation,
    conversationId ? 'ElevenLabs conversation ID: ' + conversationId : '',
    conversationId ? 'Recording / transcript: review in ElevenLabs Conversations (retained for 30 days).' : '',
    payload.failureReason ? 'Failure reason: ' + payload.failureReason : ''
  ].filter(Boolean).join('\n')
} }];
